//! This module implements the sum-check protocol used in Spartan.
//!
//! The sum-check protocol allows a prover to convince a verifier that a claimed sum
//! over a multivariate polynomial equals a specific value, without the verifier
//! needing to compute the sum directly.

use crate::{
  big_num::DelayedReduction,
  errors::SpartanError,
  polys::{
    multilinear::MultilinearPolynomial,
    univariate::{CompressedUniPoly, UniPoly},
  },
  start_span,
  traits::{
    mod_engine::SumcheckEngine,
    transcript::{ByteTranscript, TranscriptEngineTrait},
  },
};
use rayon::prelude::*;
use serde::{Deserialize, Serialize};
use tracing::info;

/// A proof generated by the sum-check protocol.
///
/// This struct contains the compressed univariate polynomials that constitute
/// the prover's messages in each round of the sum-check protocol.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(bound = "")]
pub struct SumcheckProof<
  E: SumcheckEngine<Scalar: crate::traits::PrimeFieldExt + Serialize + serde::de::DeserializeOwned>,
> {
  compressed_polys: Vec<CompressedUniPoly<E::Scalar>>,
}

impl<
  E: SumcheckEngine<Scalar: crate::traits::PrimeFieldExt + Serialize + serde::de::DeserializeOwned>,
> SumcheckProof<E>
where
  E::Scalar: crate::big_num::DelayedReduction<E::Scalar>,
{
  /// Returns a new proof with `round0_poly` prepended to the existing rounds.
  pub fn prepend_round(self, round0_poly: UniPoly<E::Scalar>) -> Self {
    let mut polys = Vec::with_capacity(1 + self.compressed_polys.len());
    polys.push(round0_poly.compress());
    polys.extend(self.compressed_polys);
    SumcheckProof {
      compressed_polys: polys,
    }
  }

  /// Verifies a sum-check proof.
  ///
  /// # Arguments
  /// * `claim` - The claimed sum that the prover asserts
  /// * `num_rounds` - The number of rounds in the sum-check protocol
  /// * `degree_bound` - The maximum degree of univariate polynomials in each round
  /// * `transcript` - The transcript for the interactive proof
  ///
  /// # Returns
  /// A tuple containing the final evaluation point and the sequence of verifier challenges,
  /// or an error if verification fails.
  pub fn verify(
    &self,
    claim: E::Scalar,
    num_rounds: usize,
    degree_bound: usize,
    transcript: &mut E::TE,
  ) -> Result<(E::Scalar, Vec<E::Scalar>), SpartanError> {
    let (_verify_span, verify_t) = start_span!("sumcheck_verify");
    let mut e = claim;
    let mut r: Vec<E::Scalar> = Vec::new();

    // verify that there is a univariate polynomial for each round
    if self.compressed_polys.len() != num_rounds {
      return Err(SpartanError::InvalidSumcheckProof);
    }

    for i in 0..self.compressed_polys.len() {
      let (_round_span, round_t) = start_span!("sumcheck_verify_round", round = i);
      let poly = self.compressed_polys[i].decompress(&e);

      // verify degree bound
      if poly.degree() != degree_bound {
        return Err(SpartanError::InvalidSumcheckProof);
      }

      // we do not need to check if poly(0) + poly(1) = e, as
      // decompress() call above already ensures that holds
      debug_assert_eq!(poly.eval_at_zero() + poly.eval_at_one(), e);

      // append the prover's message to the transcript
      transcript.absorb(b"p", &poly);

      //derive the verifier's challenge for the next round
      let r_i = transcript.squeeze(b"c")?;

      r.push(r_i);

      // evaluate the claimed degree-ell polynomial at r_i
      e = poly.evaluate(&r_i);

      if round_t.elapsed().as_millis() > 0 {
        info!(elapsed_ms = %round_t.elapsed().as_millis(), "sumcheck_verify_round");
      }
    }

    info!(elapsed_ms = %verify_t.elapsed().as_millis(), "sumcheck_verify");
    Ok((e, r))
  }

  /// Computes evaluation points for a quadratic polynomial using delayed modular reduction.
  ///
  /// Accumulates a·b products in wide limbs (no intermediate reductions),
  /// reducing only once at the end. This saves N-1 Montgomery reductions per round.
  ///
  /// # Arguments
  /// * `poly_A` - First multilinear polynomial
  /// * `poly_B` - Second multilinear polynomial
  ///
  /// # Returns
  /// A tuple `(eval_0, eval_2)` containing evaluations at points 0 and 2.
  #[inline(always)]
  fn compute_eval_points_quad(
    poly_A: &MultilinearPolynomial<E::Scalar>,
    poly_B: &MultilinearPolynomial<E::Scalar>,
  ) -> (E::Scalar, E::Scalar) {
    type Acc<S> = <S as DelayedReduction<S>>::Accumulator;

    let full_len = poly_A.Z.len() / 2;
    // Skip positions where all of A's or all of B's contributions are zero.
    let len = poly_A.eff_pairs().min(poly_B.eff_pairs()).min(full_len);

    let (acc_0, acc_inf) = (0..len)
      .into_par_iter()
      .fold(
        || (Acc::<E::Scalar>::default(), Acc::<E::Scalar>::default()),
        |mut acc, i| {
          let a_low = &poly_A[i];
          let a_high = &poly_A[full_len + i];
          let b_low = &poly_B[i];
          let b_high = &poly_B[full_len + i];

          <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
            &mut acc.0, a_low, b_low,
          );

          let delta_a = *a_high - *a_low;
          let delta_b = *b_high - *b_low;
          <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
            &mut acc.1, &delta_a, &delta_b,
          );

          acc
        },
      )
      .reduce(
        || (Acc::<E::Scalar>::default(), Acc::<E::Scalar>::default()),
        |mut a, b| {
          a.0 += b.0;
          a.1 += b.1;
          a
        },
      );

    (
      <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&acc_0),
      <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&acc_inf),
    )
  }

  /// Generates a sum-check proof for a quadratic combination of two multilinear polynomials.
  ///
  /// Uses delayed modular reduction for improved performance.
  ///
  /// # Arguments
  /// * `claim` - The claimed sum over the hypercube
  /// * `num_rounds` - The number of variables/rounds in the sum-check
  /// * `poly_A` - First multilinear polynomial (mutable, will be bound during protocol)
  /// * `poly_B` - Second multilinear polynomial (mutable, will be bound during protocol)
  /// * `transcript` - The transcript for generating randomness
  ///
  /// # Returns
  /// A tuple containing the sum-check proof, the sequence of verifier challenges,
  /// and the final evaluations of the polynomials.
  pub fn prove_quad(
    claim: &E::Scalar,
    num_rounds: usize,
    poly_A: &mut MultilinearPolynomial<E::Scalar>,
    poly_B: &mut MultilinearPolynomial<E::Scalar>,
    transcript: &mut E::TE,
  ) -> Result<(Self, Vec<E::Scalar>, Vec<E::Scalar>), SpartanError> {
    let mut r: Vec<E::Scalar> = Vec::new();
    let mut polys: Vec<CompressedUniPoly<E::Scalar>> = Vec::new();
    let mut claim_per_round = *claim;
    for round in 0..num_rounds {
      let (_round_span, round_t) = start_span!("sumcheck_quad_round", round = round);

      let poly = {
        let (_eval_span, eval_t) = start_span!("compute_eval_points_quad");
        let (eval_point_0, t_inf) = Self::compute_eval_points_quad(poly_A, poly_B);
        if eval_t.elapsed().as_millis() > 0 {
          info!(elapsed_ms = %eval_t.elapsed().as_millis(), "compute_eval_points_quad");
        }

        // BDDT: derive eval_2 from claim, eval_0, and t(inf)
        // t(X) = a_0 + a_1X + a_2X^2; t(inf)=a_2; t(0)=a_0; claim=t(0)+t(1)=2a_0+a_1+a_2
        // eval_2 = t(2) = a_0 + 2a_1 + 4a_2 = 2*claim - 3*eval_0 + 2*t_inf
        let three_eval0 = eval_point_0 + eval_point_0 + eval_point_0;
        let eval_point_2 = claim_per_round + claim_per_round - three_eval0 + t_inf + t_inf;
        let evals = vec![eval_point_0, claim_per_round - eval_point_0, eval_point_2];
        UniPoly::from_evals(&evals)?
      };

      // append the prover's message to the transcript
      transcript.absorb(b"p", &poly);

      //derive the verifier's challenge for the next round
      let r_i = transcript.squeeze(b"c")?;
      r.push(r_i);
      polys.push(poly.compress());

      // Set up next round
      claim_per_round = poly.evaluate(&r_i);

      // bind all tables to the verifier's challenge
      let (_bind_span, bind_t) = start_span!("bind_poly_vars_quad");
      rayon::join(
        || poly_A.bind_poly_var_top(&r_i),
        || poly_B.bind_poly_var_top(&r_i),
      );
      info!(elapsed_ms = %bind_t.elapsed().as_millis(), "bind_poly_vars_quad");
      info!(elapsed_ms = %round_t.elapsed().as_millis(), round = round, "sumcheck_quad_round");
    }

    Ok((
      SumcheckProof {
        compressed_polys: polys,
      },
      r,
      vec![poly_A[0], poly_B[0]],
    ))
  }

  /// Prove poly_A * poly_B - poly_C using optimized equality polynomial handling
  /// with delayed modular reduction for improved performance.
  pub fn prove_cubic_with_three_inputs(
    claim: &E::Scalar,
    taus: Vec<E::Scalar>,
    poly_A: &mut MultilinearPolynomial<E::Scalar>,
    poly_B: &mut MultilinearPolynomial<E::Scalar>,
    poly_C: &mut MultilinearPolynomial<E::Scalar>,
    transcript: &mut E::TE,
  ) -> Result<(Self, Vec<E::Scalar>, Vec<E::Scalar>), SpartanError> {
    let mut r: Vec<E::Scalar> = Vec::new();
    let mut polys: Vec<CompressedUniPoly<E::Scalar>> = Vec::new();
    let mut claim_per_round = *claim;

    let num_rounds = taus.len();

    let mut eq_instance = eq_sumcheck::EqSumCheckInstance::<E>::new(taus);

    for round in 0..num_rounds {
      let (_round_span, round_t) = start_span!("sumcheck_round", round = round);

      let poly = {
        // Make an iterator returning the contributions to the evaluations
        let (_eval_span, eval_t) = start_span!("compute_eval_points");
        let (eval_point_0, eval_point_2, eval_point_3) = eq_instance
          .evaluation_points_cubic_with_three_inputs(poly_A, poly_B, poly_C, claim_per_round);
        if eval_t.elapsed().as_millis() > 0 {
          info!(elapsed_ms = %eval_t.elapsed().as_millis(), "compute_eval_points");
        }

        let evals = vec![
          eval_point_0,
          claim_per_round - eval_point_0,
          eval_point_2,
          eval_point_3,
        ];
        UniPoly::from_evals(&evals)?
      };

      // append the prover's message to the transcript
      transcript.absorb(b"p", &poly);

      //derive the verifier's challenge for the next round
      let r_i = transcript.squeeze(b"c")?;
      r.push(r_i);
      polys.push(poly.compress());

      // Set up next round
      claim_per_round = poly.evaluate(&r_i);

      // bound all tables to the verifier's challenge
      let (_bind_span, bind_t) = start_span!("bind_poly_vars");
      rayon::join(
        || poly_A.bind_poly_var_top(&r_i),
        || poly_B.bind_poly_var_top(&r_i),
      );
      rayon::join(
        || poly_C.bind_poly_var_top(&r_i),
        || eq_instance.bound(&r_i),
      );
      info!(elapsed_ms = %bind_t.elapsed().as_millis(), "bind_poly_vars");
      info!(elapsed_ms = %round_t.elapsed().as_millis(), round = round, "sumcheck_round");
    }

    Ok((
      SumcheckProof {
        compressed_polys: polys,
      },
      r,
      vec![poly_A[0], poly_B[0], poly_C[0]],
    ))
  }

  /// Outer sumcheck for Integer Mod-R1CS.
  ///
  /// Proves that `sum_i eq(i, tau) * (poly_A(i)*poly_B(i) - poly_C(i) - poly_M(i)*poly_Q(i))` equals `claim`,
  ///
  /// Round polynomial is degree 3 (same as the 3-input cubic SC).
  /// Returns `(proof, r, [v_a, v_b, v_c, v_m, v_q])`.
  pub fn prove_cubic_with_five_inputs(
    claim: &E::Scalar,
    taus: Vec<E::Scalar>,
    poly_A: &mut MultilinearPolynomial<E::Scalar>,
    poly_B: &mut MultilinearPolynomial<E::Scalar>,
    poly_C: &mut MultilinearPolynomial<E::Scalar>,
    poly_M: &mut MultilinearPolynomial<E::Scalar>,
    poly_Q: &mut MultilinearPolynomial<E::Scalar>,
    transcript: &mut E::TE,
  ) -> Result<(Self, Vec<E::Scalar>, Vec<E::Scalar>), SpartanError> {
    let mut r: Vec<E::Scalar> = Vec::new();
    let mut polys: Vec<CompressedUniPoly<E::Scalar>> = Vec::new();
    let mut claim_per_round = *claim;

    let num_rounds = taus.len();
    let mut eq_instance = eq_sumcheck::EqSumCheckInstance::<E>::new(taus);

    for round in 0..num_rounds {
      let (_round_span, round_t) = start_span!("sumcheck_round_imod", round = round);

      let poly = {
        let (eval_point_0, eval_point_2, eval_point_3) = eq_instance
          .evaluation_points_cubic_with_five_inputs(
            poly_A,
            poly_B,
            poly_C,
            poly_M,
            poly_Q,
            claim_per_round,
          );

        let evals = vec![
          eval_point_0,
          claim_per_round - eval_point_0,
          eval_point_2,
          eval_point_3,
        ];
        UniPoly::from_evals(&evals)?
      };

      transcript.absorb(b"p", &poly);
      let r_i = transcript.squeeze(b"c")?;
      r.push(r_i);
      polys.push(poly.compress());

      claim_per_round = poly.evaluate(&r_i);

      // Bind all five polynomials plus the eq instance.
      rayon::join(
        || {
          rayon::join(
            || poly_A.bind_poly_var_top(&r_i),
            || poly_B.bind_poly_var_top(&r_i),
          )
        },
        || {
          rayon::join(
            || poly_C.bind_poly_var_top(&r_i),
            || {
              rayon::join(
                || poly_M.bind_poly_var_top(&r_i),
                || poly_Q.bind_poly_var_top(&r_i),
              )
            },
          )
        },
      );
      eq_instance.bound(&r_i);
      info!(elapsed_ms = %round_t.elapsed().as_millis(), round = round, "sumcheck_round_imod");
    }

    Ok((
      SumcheckProof {
        compressed_polys: polys,
      },
      r,
      vec![poly_A[0], poly_B[0], poly_C[0], poly_M[0], poly_Q[0]],
    ))
  }
}

pub(crate) mod eq_sumcheck {
  //! Sumcheck optimization for equality polynomials.
  //!
  //! The eq-factoring structure (splitting eq into left/right halves) follows
  //! Gruen (eprint 2024/108, Section 3).
  //!
  //! The claim-derived evaluation points (computing only 2 N-scaling sums per round
  //! instead of 3) follow BDDT (eprint 2025/1117, Section 6.2).
  use crate::traits::mod_engine::SumcheckEngine;
  use crate::{big_num::DelayedReduction, polys::multilinear::MultilinearPolynomial};
  use ff::{Field, PrimeField};
  use rayon::prelude::*;
  use serde::Serialize;

  pub struct EqSumCheckInstance<
    E: SumcheckEngine<Scalar: crate::traits::PrimeFieldExt + Serialize + serde::de::DeserializeOwned>,
  > {
    // number of variables at first
    init_num_vars: usize,
    first_half: usize,
    second_half: usize,
    round: usize,
    taus: Vec<E::Scalar>,
    eval_eq_left: E::Scalar,
    poly_eq_left: Vec<Vec<E::Scalar>>,
    poly_eq_right: Vec<Vec<E::Scalar>>,
    // Per-tau precomputed values: (eq(tau, 0), eq_slope = 2*tau - 1, eq(tau, -1))
    // where eq(tau, X) = eq(tau, 0) + eq_slope * X
    eq_tau_0_slope_m1: Vec<(E::Scalar, E::Scalar, E::Scalar)>,
  }

  impl<
    E: SumcheckEngine<Scalar: crate::traits::PrimeFieldExt + Serialize + serde::de::DeserializeOwned>,
  > EqSumCheckInstance<E>
  where
    E::Scalar: crate::big_num::DelayedReduction<E::Scalar>,
  {
    /// Creates a new EqSumCheckInstance for optimized sumcheck with equality polynomials.
    ///
    /// The algorithm splits the tau vector and precomputes equality polynomial evaluations
    /// for efficient lookup during the sumcheck rounds. The round counter starts at 1 (not 0)
    /// to simplify indexing into precomputed arrays, as the first evaluation happens before
    /// any binding operations occur.
    pub fn new(taus: Vec<E::Scalar>) -> Self {
      let l = taus.len();
      let first_half = l / 2;

      let compute_eq_polynomials = |taus: Vec<&E::Scalar>| -> Vec<Vec<E::Scalar>> {
        let len = taus.len();
        let mut result = Vec::with_capacity(len + 1);

        result.push(vec![E::Scalar::ONE]);

        for i in 0..len {
          let tau = taus[i];

          let prev = &result[i];
          let mut v_next = prev.to_vec();
          v_next.par_extend(prev.par_iter().map(|v| *v * tau));
          let (first, last) = v_next.split_at_mut(prev.len());
          first.par_iter_mut().zip(last).for_each(|(a, b)| *a -= *b);

          result.push(v_next);
        }

        result
      };

      let (left_taus, right_taus) = taus.split_at(first_half);
      // Skip the first element of left_taus because the equality polynomial evaluation
      // for the first variable is tracked separately in eval_eq_left (initialized to 1).
      // This matches the Nova optimization approach where the left part is processed
      // incrementally through the bound() method rather than via lookup tables.
      let left_taus = left_taus.iter().skip(1).rev().collect::<Vec<_>>();
      let right_taus = right_taus.iter().rev().collect::<Vec<_>>();

      let (poly_eq_left, poly_eq_right) = rayon::join(
        || compute_eq_polynomials(left_taus),
        || compute_eq_polynomials(right_taus),
      );

      let eq_tau_0_slope_m1 = taus
        .par_iter()
        .map(|tau| {
          // eq(tau, X) = (1 - tau) + (2*tau - 1) * X
          let one_minus_tau = E::Scalar::ONE - tau;
          let two_tau_minus_one = *tau - one_minus_tau; // 2*tau - 1
          let eq_m1 = one_minus_tau - two_tau_minus_one; // 2 - 3*tau
          (one_minus_tau, two_tau_minus_one, eq_m1)
        })
        .collect::<Vec<_>>();

      Self {
        init_num_vars: l,
        first_half,
        second_half: l - first_half,
        round: 1, // Start at 1 to simplify array indexing (round-1 gives 0-based index)
        taus,
        eval_eq_left: E::Scalar::ONE,
        poly_eq_left,
        poly_eq_right,
        eq_tau_0_slope_m1,
      }
    }

    /// Evaluate eq(tau,X) * (A*B - C) using 2 N-scaling sums instead of 3
    /// (BDDT, eprint 2025/1117, Section 6.2).
    ///
    /// Computes only t(0) and t(inf) (the leading coefficient), then derives the
    /// remaining evaluation points from the sumcheck claim in O(1).
    /// Falls back to computing all 3 sums when tau=0 makes derivation impossible.
    #[inline]
    pub fn evaluation_points_cubic_with_three_inputs(
      &self,
      poly_A: &MultilinearPolynomial<E::Scalar>,
      poly_B: &MultilinearPolynomial<E::Scalar>,
      poly_C: &MultilinearPolynomial<E::Scalar>,
      claim: E::Scalar,
    ) -> (E::Scalar, E::Scalar, E::Scalar) {
      debug_assert_eq!(poly_A.Z.len() % 2, 0);

      type Acc<S> = <S as DelayedReduction<S>>::Accumulator;

      let in_first_half = self.round < self.first_half;
      let half_p = poly_A.Z.len() / 2;

      // Compute 2 N-scaling sums: t(0) = sum E~(x)*(A_0B_0-C_0) and
      // t(inf) = sum E~(x)*(A_1-A_0)(B_1-B_0) [leading coefficient of inner polynomial]
      let (t_0, t_inf) = if in_first_half {
        let (poly_eq_left, poly_eq_right, second_half) = self.poly_eqs_first_half();
        let eq_out_len = poly_eq_left.len();

        let (acc_0, acc_inf) = (0..eq_out_len)
          .into_par_iter()
          .fold(
            || (Acc::<E::Scalar>::default(), Acc::<E::Scalar>::default()),
            |mut outer_acc, x_out| {
              let e_out = &poly_eq_left[x_out];
              let mut inner_0 = Acc::<E::Scalar>::default();
              let mut inner_inf = Acc::<E::Scalar>::default();

              for (x_in, e_in) in poly_eq_right.iter().enumerate() {
                let id = (x_out << second_half) | x_in;

                let (zero_a, one_a) = (&poly_A.Z[id], &poly_A.Z[id + half_p]);
                let (zero_b, one_b) = (&poly_B.Z[id], &poly_B.Z[id + half_p]);
                let zero_c = &poly_C.Z[id];

                let t_0_elem = *zero_a * *zero_b - *zero_c;
                let t_inf_elem = (*one_a - *zero_a) * (*one_b - *zero_b);

                <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
                  &mut inner_0,
                  e_in,
                  &t_0_elem,
                );
                <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
                  &mut inner_inf,
                  e_in,
                  &t_inf_elem,
                );
              }

              let inner_0_red = <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&inner_0);
              let inner_inf_red = <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&inner_inf);

              <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
                &mut outer_acc.0,
                e_out,
                &inner_0_red,
              );
              <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
                &mut outer_acc.1,
                e_out,
                &inner_inf_red,
              );

              outer_acc
            },
          )
          .reduce(
            || (Acc::<E::Scalar>::default(), Acc::<E::Scalar>::default()),
            |mut a, b| {
              a.0 += b.0;
              a.1 += b.1;
              a
            },
          );

        (
          <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&acc_0),
          <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&acc_inf),
        )
      } else {
        let poly_eq_right = self.poly_eq_right_last_half();

        let (acc_0, acc_inf) = (0..half_p)
          .into_par_iter()
          .fold(
            || (Acc::<E::Scalar>::default(), Acc::<E::Scalar>::default()),
            |mut acc, id| {
              let e = &poly_eq_right[id];

              let (zero_a, one_a) = (&poly_A.Z[id], &poly_A.Z[id + half_p]);
              let (zero_b, one_b) = (&poly_B.Z[id], &poly_B.Z[id + half_p]);
              let zero_c = &poly_C.Z[id];

              let t_0_elem = *zero_a * *zero_b - *zero_c;
              let t_inf_elem = (*one_a - *zero_a) * (*one_b - *zero_b);

              <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
                &mut acc.0, e, &t_0_elem,
              );
              <E::Scalar as DelayedReduction<E::Scalar>>::unreduced_multiply_accumulate(
                &mut acc.1,
                e,
                &t_inf_elem,
              );

              acc
            },
          )
          .reduce(
            || (Acc::<E::Scalar>::default(), Acc::<E::Scalar>::default()),
            |mut a, b| {
              a.0 += b.0;
              a.1 += b.1;
              a
            },
          );

        (
          <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&acc_0),
          <E::Scalar as DelayedReduction<E::Scalar>>::reduce(&acc_inf),
        )
      };

      // Derive evaluation points from claim (BDDT)
      if let Some(result) = self.derive_from_claim(t_0, t_inf, claim) {
        result
      } else {
        self.fallback_three_inputs(t_0, t_inf, claim, poly_A, poly_B, poly_C)
      }
    }

    /// Evaluate eq(tau,X) * (A*B - C - M*Q) for the Integer Mod-R1CS outer sumcheck.
    /// Same BDDT structure as the 3-input variant but with an extra `-M*Q` quadratic
    /// term in the inner polynomial. Leading coefficient picks up `-(m_1-m_0)(q_1-q_0)`.
    #[inline]
    pub fn evaluation_points_cubic_with_five_inputs(
      &self,
      poly_A: &MultilinearPolynomial<E::Scalar>,
      poly_B: &MultilinearPolynomial<E::Scalar>,
      poly_C: &MultilinearPolynomial<E::Scalar>,
      poly_M: &MultilinearPolynomial<E::Scalar>,
      poly_Q: &MultilinearPolynomial<E::Scalar>,
      claim: E::Scalar,
    ) -> (E::Scalar, E::Scalar, E::Scalar) {
      debug_assert_eq!(poly_A.Z.len() % 2, 0);

      let in_first_half = self.round < self.first_half;
      let half_p = poly_A.Z.len() / 2;

      // t(0)   = sum_x eq~(x) * (A_0 B_0 - C_0 - M_0 Q_0)
      // t(inf) = sum_x eq~(x) * ((A_1-A_0)(B_1-B_0) - (M_1-M_0)(Q_1-Q_0))
      //
      // Note: we do not use the wide-accumulator delayed-reduction path here
      // because the integrand mixes two quadratic terms with opposite signs;
      // the existing accumulator API only accumulates products. A normal
      // field-multiply path is plenty for now; revisit if this is hot.
      let (t_0, t_inf) = if in_first_half {
        let (poly_eq_left, poly_eq_right, second_half) = self.poly_eqs_first_half();
        let eq_out_len = poly_eq_left.len();

        (0..eq_out_len)
          .into_par_iter()
          .map(|x_out| {
            let e_out = poly_eq_left[x_out];
            let (inner_0, inner_inf): (E::Scalar, E::Scalar) = poly_eq_right
              .iter()
              .enumerate()
              .map(|(x_in, e_in)| {
                let id = (x_out << second_half) | x_in;

                let a0 = poly_A.Z[id];
                let a1 = poly_A.Z[id + half_p];
                let b0 = poly_B.Z[id];
                let b1 = poly_B.Z[id + half_p];
                let c0 = poly_C.Z[id];
                let m0 = poly_M.Z[id];
                let m1 = poly_M.Z[id + half_p];
                let q0 = poly_Q.Z[id];
                let q1 = poly_Q.Z[id + half_p];

                let t0_elem = a0 * b0 - c0 - m0 * q0;
                let tinf_elem = (a1 - a0) * (b1 - b0) - (m1 - m0) * (q1 - q0);
                (*e_in * t0_elem, *e_in * tinf_elem)
              })
              .fold((E::Scalar::ZERO, E::Scalar::ZERO), |acc, x| {
                (acc.0 + x.0, acc.1 + x.1)
              });
            (e_out * inner_0, e_out * inner_inf)
          })
          .reduce(
            || (E::Scalar::ZERO, E::Scalar::ZERO),
            |a, b| (a.0 + b.0, a.1 + b.1),
          )
      } else {
        let poly_eq_right = self.poly_eq_right_last_half();

        (0..half_p)
          .into_par_iter()
          .map(|id| {
            let e = poly_eq_right[id];
            let a0 = poly_A.Z[id];
            let a1 = poly_A.Z[id + half_p];
            let b0 = poly_B.Z[id];
            let b1 = poly_B.Z[id + half_p];
            let c0 = poly_C.Z[id];
            let m0 = poly_M.Z[id];
            let m1 = poly_M.Z[id + half_p];
            let q0 = poly_Q.Z[id];
            let q1 = poly_Q.Z[id + half_p];

            let t0_elem = a0 * b0 - c0 - m0 * q0;
            let tinf_elem = (a1 - a0) * (b1 - b0) - (m1 - m0) * (q1 - q0);
            (e * t0_elem, e * tinf_elem)
          })
          .reduce(
            || (E::Scalar::ZERO, E::Scalar::ZERO),
            |a, b| (a.0 + b.0, a.1 + b.1),
          )
      };

      if let Some(result) = self.derive_from_claim(t_0, t_inf, claim) {
        result
      } else {
        self.fallback_five_inputs(t_0, t_inf, claim, poly_A, poly_B, poly_C, poly_M, poly_Q)
      }
    }

    /// Fallback for the 5-input cubic SC when `derive_from_claim` cannot invert
    /// (i.e. tau_i = 0): compute t(-1) directly.
    fn fallback_five_inputs(
      &self,
      t_0: E::Scalar,
      t_inf: E::Scalar,
      claim: E::Scalar,
      poly_A: &MultilinearPolynomial<E::Scalar>,
      poly_B: &MultilinearPolynomial<E::Scalar>,
      poly_C: &MultilinearPolynomial<E::Scalar>,
      poly_M: &MultilinearPolynomial<E::Scalar>,
      poly_Q: &MultilinearPolynomial<E::Scalar>,
    ) -> (E::Scalar, E::Scalar, E::Scalar) {
      let p = self.eval_eq_left;
      let (eq_0, eq_slope, eq_m1) = self.eq_tau_0_slope_m1[self.round - 1];
      let half_p = poly_A.Z.len() / 2;

      // t(-1) = sum eq~(x) * ((2A_0-A_1)(2B_0-B_1) - (2C_0-C_1) - (2M_0-M_1)(2Q_0-Q_1))
      let t_m1: E::Scalar = if self.round < self.first_half {
        let (poly_eq_left, poly_eq_right, second_half) = self.poly_eqs_first_half();
        let eq_out_len = poly_eq_left.len();
        (0..eq_out_len)
          .into_par_iter()
          .map(|x_out| {
            let e_out = poly_eq_left[x_out];
            let inner: E::Scalar = poly_eq_right
              .iter()
              .enumerate()
              .map(|(x_in, e_in)| {
                let id = (x_out << second_half) | x_in;
                let m1_a = poly_A.Z[id].double() - poly_A.Z[id + half_p];
                let m1_b = poly_B.Z[id].double() - poly_B.Z[id + half_p];
                let m1_c = poly_C.Z[id].double() - poly_C.Z[id + half_p];
                let m1_m = poly_M.Z[id].double() - poly_M.Z[id + half_p];
                let m1_q = poly_Q.Z[id].double() - poly_Q.Z[id + half_p];
                *e_in * (m1_a * m1_b - m1_c - m1_m * m1_q)
              })
              .sum();
            e_out * inner
          })
          .sum()
      } else {
        let poly_eq_right = self.poly_eq_right_last_half();
        (0..half_p)
          .into_par_iter()
          .map(|id| {
            let e = poly_eq_right[id];
            let m1_a = poly_A.Z[id].double() - poly_A.Z[id + half_p];
            let m1_b = poly_B.Z[id].double() - poly_B.Z[id + half_p];
            let m1_c = poly_C.Z[id].double() - poly_C.Z[id + half_p];
            let m1_m = poly_M.Z[id].double() - poly_M.Z[id + half_p];
            let m1_q = poly_Q.Z[id].double() - poly_Q.Z[id + half_p];
            e * (m1_a * m1_b - m1_c - m1_m * m1_q)
          })
          .sum()
      };

      let s_0 = eq_0 * p * t_0;
      let s_leading = eq_slope * p * t_inf;
      let s_m1 = eq_m1 * p * t_m1;

      let e0 = s_0;
      let e1: E::Scalar = claim - s_0;
      let half: E::Scalar = E::Scalar::TWO_INV;
      let c1: E::Scalar = (e1 - s_m1) * half - s_leading;
      let c2: E::Scalar = (e1 + s_m1) * half - e0;

      let inner_2: E::Scalar = c2 + s_leading.double();
      let eval_2: E::Scalar = e0 + (c1 + inner_2.double()).double();

      let c3_3: E::Scalar = s_leading.double() + s_leading;
      let inner_3: E::Scalar = c2 + c3_3;
      let mid_3: E::Scalar = c1 + inner_3.double() + inner_3;
      let eval_3: E::Scalar = e0 + mid_3.double() + mid_3;

      (e0, eval_2, eval_3)
    }

    ///
    /// Returns `None` when tau=0 (l(1)=0), requiring the caller to fall back
    /// to computing the third N-scaling sum directly.
    #[inline]
    fn derive_from_claim(
      &self,
      t_0: E::Scalar,
      t_inf: E::Scalar,
      claim: E::Scalar,
    ) -> Option<(E::Scalar, E::Scalar, E::Scalar)> {
      let p = self.eval_eq_left;
      let (eq_0, eq_slope, eq_m1) = self.eq_tau_0_slope_m1[self.round - 1];

      // l(X) = eq(tau_i, X) = eq_0 + eq_slope*X
      let l_0_p = eq_0 * p;
      let l_1_p = (eq_0 + eq_slope) * p; // = tau_i * eval_eq_left

      // When tau=0, l(1)=0 and we can't invert
      let l_1_p_inv: Option<E::Scalar> = l_1_p.invert().into();
      let l_1_p_inv = l_1_p_inv?;

      // s(0) = l(0) * p * t(0)
      let s_0 = l_0_p * t_0;
      let s_1 = claim - s_0;
      let t_1 = s_1 * l_1_p_inv;

      // Cubic coefficient of s: s_leading = eq_slope * p * t(inf)
      let s_leading = eq_slope * p * t_inf;

      // t is degree 2, so t(-1) = 2*t(inf) + 2*t(0) - t(1)
      let t_m1 = t_inf.double() + t_0.double() - t_1;
      let s_m1 = eq_m1 * p * t_m1;

      // Convert (s(0), s_leading, s(-1)) to (eval_0, eval_2, eval_3)
      let e0 = s_0;
      let e1 = s_1;
      let half: E::Scalar = E::Scalar::TWO_INV;
      let c1: E::Scalar = (e1 - s_m1) * half - s_leading;
      let c2: E::Scalar = (e1 + s_m1) * half - e0;

      // p(2) = e0 + 2*c1 + 4*c2 + 8*c3 via Horner: e0 + 2*(c1 + 2*(c2 + 2*c3))
      let inner_2: E::Scalar = c2 + s_leading.double();
      let eval_2: E::Scalar = e0 + (c1 + inner_2.double()).double();

      // p(3) = e0 + 3*c1 + 9*c2 + 27*c3 via Horner: e0 + 3*(c1 + 3*(c2 + 3*c3))
      let c3_3: E::Scalar = s_leading.double() + s_leading;
      let inner_3: E::Scalar = c2 + c3_3;
      let mid_3: E::Scalar = c1 + inner_3.double() + inner_3;
      let eval_3: E::Scalar = e0 + mid_3.double() + mid_3;

      Some((e0, eval_2, eval_3))
    }

    /// Fallback when derive_from_claim fails (tau=0): compute t(-1) via third N-scaling sum.
    fn fallback_three_inputs(
      &self,
      t_0: E::Scalar,
      t_inf: E::Scalar,
      claim: E::Scalar,
      poly_A: &MultilinearPolynomial<E::Scalar>,
      poly_B: &MultilinearPolynomial<E::Scalar>,
      poly_C: &MultilinearPolynomial<E::Scalar>,
    ) -> (E::Scalar, E::Scalar, E::Scalar) {
      let p = self.eval_eq_left;
      let (eq_0, eq_slope, eq_m1) = self.eq_tau_0_slope_m1[self.round - 1];
      let half_p = poly_A.Z.len() / 2;

      // Compute t(-1) = sum E~(x) * ((2A_0-A_1)(2B_0-B_1) - (2C_0-C_1))
      let t_m1: E::Scalar = if self.round < self.first_half {
        let (poly_eq_left, poly_eq_right, second_half) = self.poly_eqs_first_half();
        let eq_out_len = poly_eq_left.len();
        (0..eq_out_len)
          .into_par_iter()
          .map(|x_out| {
            let e_out = poly_eq_left[x_out];
            let inner: E::Scalar = poly_eq_right
              .iter()
              .enumerate()
              .map(|(x_in, e_in)| {
                let id = (x_out << second_half) | x_in;
                let m1_a = poly_A.Z[id].double() - poly_A.Z[id + half_p];
                let m1_b = poly_B.Z[id].double() - poly_B.Z[id + half_p];
                let m1_c = poly_C.Z[id].double() - poly_C.Z[id + half_p];
                *e_in * (m1_a * m1_b - m1_c)
              })
              .sum();
            e_out * inner
          })
          .sum()
      } else {
        let poly_eq_right = self.poly_eq_right_last_half();
        (0..half_p)
          .into_par_iter()
          .map(|id| {
            let e = poly_eq_right[id];
            let m1_a = poly_A.Z[id].double() - poly_A.Z[id + half_p];
            let m1_b = poly_B.Z[id].double() - poly_B.Z[id + half_p];
            let m1_c = poly_C.Z[id].double() - poly_C.Z[id + half_p];
            e * (m1_a * m1_b - m1_c)
          })
          .sum()
      };

      let s_0 = eq_0 * p * t_0;
      let s_leading = eq_slope * p * t_inf;
      let s_m1 = eq_m1 * p * t_m1;

      // Convert to (eval_0, eval_2, eval_3)
      let e0 = s_0;
      let e1: E::Scalar = claim - s_0;
      let half: E::Scalar = E::Scalar::TWO_INV;
      let c1: E::Scalar = (e1 - s_m1) * half - s_leading;
      let c2: E::Scalar = (e1 + s_m1) * half - e0;

      let inner_2: E::Scalar = c2 + s_leading.double();
      let eval_2: E::Scalar = e0 + (c1 + inner_2.double()).double();

      let c3_3: E::Scalar = s_leading.double() + s_leading;
      let inner_3: E::Scalar = c2 + c3_3;
      let mid_3: E::Scalar = c1 + inner_3.double() + inner_3;
      let eval_3: E::Scalar = e0 + mid_3.double() + mid_3;

      (e0, eval_2, eval_3)
    }

    #[inline]
    pub fn bound(&mut self, r: &E::Scalar) {
      // Invariant: self.round is always >= 1 when bound is called
      // as it's initialized to 1 in new() and only incremented here
      let tau = self.taus[self.round - 1];
      self.eval_eq_left *= E::Scalar::ONE - tau - r + (*r * tau).double();
      self.round += 1;
    }

    #[inline]
    fn poly_eqs_first_half(&self) -> (&Vec<E::Scalar>, &Vec<E::Scalar>, usize) {
      let second_half = self.second_half;
      // Safe indexing: This method is only called when in_first_half is true,
      // which means self.round < self.first_half. Therefore self.first_half - self.round > 0
      // and the index is valid. The poly_eq_left array has first_half+1 elements (0..=first_half).
      let poly_eq_left = &self.poly_eq_left[self.first_half - self.round];
      let poly_eq_right = &self.poly_eq_right[second_half];

      debug_assert_eq!(poly_eq_right.len(), 1 << second_half);

      (poly_eq_left, poly_eq_right, second_half)
    }

    #[inline]
    fn poly_eq_right_last_half(&self) -> &Vec<E::Scalar> {
      // Safe indexing: This method is only called when in_first_half is false,
      // which means self.round >= self.first_half. The maximum value of self.round
      // is init_num_vars (as we do init_num_vars rounds), so the index is always >= 0.
      &self.poly_eq_right[self.init_num_vars - self.round]
    }
  }
}

#[cfg(test)]
mod perf_tests {
  use super::*;
  use crate::{
    big_num::DelayedReduction, polys::multilinear::MultilinearPolynomial, start_span,
    traits::Engine,
  };
  use ff::Field;
  use rand::{SeedableRng, rngs::StdRng};
  use tracing::info;
  use tracing_subscriber::EnvFilter;

  // Test sizes: smaller for debug builds, full range for release
  #[cfg(debug_assertions)]
  const TEST_SIZES: &[usize] = &[16, 18];

  #[cfg(not(debug_assertions))]
  const TEST_SIZES: &[usize] = &[16, 18, 20, 22, 24];

  fn test_first_round_spartan_sumcheck_with<E: Engine>()
  where
    E::Scalar: DelayedReduction<E::Scalar>,
  {
    const SEED: u64 = 0xDEADBEEF;
    let field_name = std::any::type_name::<E::Scalar>()
      .split("::")
      .last()
      .unwrap_or("unknown");

    for &num_vars in TEST_SIZES {
      let len = 1 << num_vars;
      let mut rng = StdRng::seed_from_u64(SEED);

      let az: Vec<E::Scalar> = (0..len).map(|_| E::Scalar::random(&mut rng)).collect();
      let bz: Vec<E::Scalar> = (0..len).map(|_| E::Scalar::random(&mut rng)).collect();
      let cz: Vec<E::Scalar> = (0..len).map(|_| E::Scalar::random(&mut rng)).collect();
      let taus: Vec<E::Scalar> = (0..num_vars).map(|_| E::Scalar::random(&mut rng)).collect();

      let mut poly_az = MultilinearPolynomial::new(az);
      let mut poly_bz = MultilinearPolynomial::new(bz);
      let mut poly_cz = MultilinearPolynomial::new(cz);
      let mut transcript = E::TE::new(b"perf_test");

      let (_span, t) = start_span!("sumcheck_prove", field = field_name, num_vars = num_vars);

      let (proof, _r, _evals) = SumcheckProof::<E>::prove_cubic_with_three_inputs(
        &E::Scalar::ZERO,
        taus,
        &mut poly_az,
        &mut poly_bz,
        &mut poly_cz,
        &mut transcript,
      )
      .expect("proof generation should succeed");

      info!(field = field_name, num_vars, n = len, ms = ?t.elapsed().as_millis(), "completed");

      // Verify proof with fresh transcript
      let mut verifier_transcript = E::TE::new(b"perf_test");
      proof
        .verify(E::Scalar::ZERO, num_vars, 3, &mut verifier_transcript)
        .expect("proof verification should succeed");
    }
  }

  #[test]
  fn test_first_round_spartan_sumcheck() {
    let _ = tracing_subscriber::fmt()
      .with_target(false)
      .with_ansi(true)
      .with_env_filter(EnvFilter::from_default_env())
      .try_init();

    use crate::provider::Bn254Engine;

    // Always test with BN254
    test_first_round_spartan_sumcheck_with::<Bn254Engine>();

    // Additional engines only in release builds
    #[cfg(not(debug_assertions))]
    {
      use crate::provider::{PallasHyraxEngine, T256HyraxEngine};
      test_first_round_spartan_sumcheck_with::<PallasHyraxEngine>();
      test_first_round_spartan_sumcheck_with::<T256HyraxEngine>();
    }
  }

  fn test_inner_sumcheck_with<E: Engine>()
  where
    E::Scalar: DelayedReduction<E::Scalar>,
  {
    const SEED: u64 = 0xDEADBEEF;
    let field_name = std::any::type_name::<E::Scalar>()
      .split("::")
      .last()
      .unwrap_or("unknown");

    for &num_vars in TEST_SIZES {
      let len = 1 << num_vars;
      let mut rng = StdRng::seed_from_u64(SEED);

      let poly_a: Vec<E::Scalar> = (0..len).map(|_| E::Scalar::random(&mut rng)).collect();
      let poly_b: Vec<E::Scalar> = (0..len).map(|_| E::Scalar::random(&mut rng)).collect();
      let claim: E::Scalar = poly_a.par_iter().zip(&poly_b).map(|(a, b)| *a * *b).sum();

      let mut poly_a = MultilinearPolynomial::new(poly_a);
      let mut poly_b = MultilinearPolynomial::new(poly_b);
      let mut transcript = E::TE::new(b"test_inner_sumcheck");

      let (_span, t) = start_span!("prove_quad", field = field_name, num_vars = num_vars);

      let (proof, _r, _evals) =
        SumcheckProof::<E>::prove_quad(&claim, num_vars, &mut poly_a, &mut poly_b, &mut transcript)
          .expect("proof generation should succeed");

      info!(field = field_name, num_vars, n = len, ms = ?t.elapsed().as_millis(), "completed");

      let mut verifier_transcript = E::TE::new(b"test_inner_sumcheck");
      proof
        .verify(claim, num_vars, 2, &mut verifier_transcript)
        .expect("proof verification should succeed");
    }
  }

  #[test]
  fn test_inner_sumcheck() {
    let _ = tracing_subscriber::fmt()
      .with_target(false)
      .with_ansi(true)
      .with_env_filter(EnvFilter::from_default_env())
      .try_init();

    use crate::provider::Bn254Engine;
    test_inner_sumcheck_with::<Bn254Engine>();

    #[cfg(not(debug_assertions))]
    {
      use crate::provider::{PallasHyraxEngine, T256HyraxEngine};
      test_inner_sumcheck_with::<PallasHyraxEngine>();
      test_inner_sumcheck_with::<T256HyraxEngine>();
    }
  }
}

#[cfg(test)]
mod five_input_tests {
  //! Correctness tests for the 5-input cubic SC added for IntMod-R1CS.
  //!
  //! The existing perf_tests pass `claim = 0` regardless of the inputs, which
  //! makes them smoke tests rather than correctness tests (the SC verifier
  //! only checks intra-round consistency, not that the initial claim matches
  //! the actual sum). These tests use the true sum over the hypercube as the
  //! claim, then additionally verify that the SC's final claim equals the
  //! integrand evaluated at the verifier's challenge `r`.
  use super::*;
  use crate::polys::eq::EqPolynomial;
  use crate::traits::Engine;
  use ff::Field;
  use rand::{SeedableRng, rngs::StdRng};

  /// Compute `sum_i eq(i, tau) * (A_i B_i - C_i - M_i Q_i)` over the hypercube.
  fn hypercube_sum<E: Engine>(
    a: &[E::Scalar],
    b: &[E::Scalar],
    c: &[E::Scalar],
    m: &[E::Scalar],
    q: &[E::Scalar],
    tau: &[E::Scalar],
  ) -> E::Scalar {
    let eq = EqPolynomial::evals_from_points(tau);
    (0..a.len())
      .map(|i| eq[i] * (a[i] * b[i] - c[i] - m[i] * q[i]))
      .fold(E::Scalar::ZERO, |acc, x| acc + x)
  }

  /// End-to-end correctness on random inputs: compute the true sum, prove
  /// with that sum as the claim, verify, and check that the final-round
  /// claim returned by the verifier equals `eq(r,τ) · (v_a v_b - v_c - v_m v_q)`.
  fn random_correctness_with<E: Engine>() {
    const SEED: u64 = 0xCAFEBABE;
    let num_vars = 5usize;
    let n = 1usize << num_vars;
    let mut rng = StdRng::seed_from_u64(SEED);

    let a: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let b: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let c: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let m: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let q: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let tau: Vec<_> = (0..num_vars).map(|_| E::Scalar::random(&mut rng)).collect();

    let claim = hypercube_sum::<E>(&a, &b, &c, &m, &q, &tau);

    let mut poly_a = MultilinearPolynomial::new(a);
    let mut poly_b = MultilinearPolynomial::new(b);
    let mut poly_c = MultilinearPolynomial::new(c);
    let mut poly_m = MultilinearPolynomial::new(m);
    let mut poly_q = MultilinearPolynomial::new(q);

    let mut p_t = E::TE::new(b"five_input_test");
    let (proof, r, evals) = SumcheckProof::<E>::prove_cubic_with_five_inputs(
      &claim,
      tau.clone(),
      &mut poly_a,
      &mut poly_b,
      &mut poly_c,
      &mut poly_m,
      &mut poly_q,
      &mut p_t,
    )
    .expect("prover");

    let mut v_t = E::TE::new(b"five_input_test");
    let (final_claim, r_v) = proof
      .verify(claim, num_vars, 3, &mut v_t)
      .expect("verifier");

    assert_eq!(r, r_v);
    let (v_a, v_b, v_c, v_m, v_q) = (evals[0], evals[1], evals[2], evals[3], evals[4]);
    let eq_tau_r = EqPolynomial::new(tau).evaluate(&r);
    let expected = eq_tau_r * (v_a * v_b - v_c - v_m * v_q);
    assert_eq!(
      final_claim, expected,
      "integrand at r doesn't match final claim"
    );
  }

  /// Zero-check correctness: choose A, B, C, M, Q so that AB - C - MQ = 0 on
  /// the hypercube (set C := AB - MQ pointwise). Sum is 0, the SC should
  /// succeed with `claim = 0`, and the final-claim consistency check holds.
  fn zero_check_correctness_with<E: Engine>() {
    const SEED: u64 = 0xC0FFEE;
    let num_vars = 5usize;
    let n = 1usize << num_vars;
    let mut rng = StdRng::seed_from_u64(SEED);

    let a: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let b: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let m: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let q: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let c: Vec<_> = (0..n).map(|i| a[i] * b[i] - m[i] * q[i]).collect();
    let tau: Vec<_> = (0..num_vars).map(|_| E::Scalar::random(&mut rng)).collect();

    assert_eq!(
      hypercube_sum::<E>(&a, &b, &c, &m, &q, &tau),
      E::Scalar::ZERO
    );

    let mut poly_a = MultilinearPolynomial::new(a);
    let mut poly_b = MultilinearPolynomial::new(b);
    let mut poly_c = MultilinearPolynomial::new(c);
    let mut poly_m = MultilinearPolynomial::new(m);
    let mut poly_q = MultilinearPolynomial::new(q);

    let mut p_t = E::TE::new(b"zero_check");
    let (proof, r, evals) = SumcheckProof::<E>::prove_cubic_with_five_inputs(
      &E::Scalar::ZERO,
      tau.clone(),
      &mut poly_a,
      &mut poly_b,
      &mut poly_c,
      &mut poly_m,
      &mut poly_q,
      &mut p_t,
    )
    .expect("prover");

    let mut v_t = E::TE::new(b"zero_check");
    let (final_claim, _r_v) = proof
      .verify(E::Scalar::ZERO, num_vars, 3, &mut v_t)
      .expect("verifier");

    let (v_a, v_b, v_c, v_m, v_q) = (evals[0], evals[1], evals[2], evals[3], evals[4]);
    let eq_tau_r = EqPolynomial::new(tau).evaluate(&r);
    let expected = eq_tau_r * (v_a * v_b - v_c - v_m * v_q);
    assert_eq!(final_claim, expected);
  }

  /// When `M = Q = 0` everywhere, the 5-input cubic reduces to the 3-input
  /// cubic (the `−M·Q` term contributes nothing to either `t_0` or `t_inf`).
  /// We expect byte-identical proofs.
  fn matches_three_input_when_mq_zero_with<E: Engine>() {
    const SEED: u64 = 0xDEADBEEF;
    let num_vars = 4usize;
    let n = 1usize << num_vars;
    let mut rng = StdRng::seed_from_u64(SEED);

    let a: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let b: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let c: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let tau: Vec<_> = (0..num_vars).map(|_| E::Scalar::random(&mut rng)).collect();
    let zero: Vec<_> = vec![E::Scalar::ZERO; n];

    // Use the true sum so the proofs are correct on both sides; otherwise the
    // 3-input variant produces internally consistent but semantically wrong
    // round polynomials, and we'd be comparing apples to a different apple.
    let claim = hypercube_sum::<E>(&a, &b, &c, &zero, &zero, &tau);

    // 3-input run
    let mut p3a = MultilinearPolynomial::new(a.clone());
    let mut p3b = MultilinearPolynomial::new(b.clone());
    let mut p3c = MultilinearPolynomial::new(c.clone());
    let mut t3 = E::TE::new(b"compare");
    let (proof3, r3, evals3) = SumcheckProof::<E>::prove_cubic_with_three_inputs(
      &claim,
      tau.clone(),
      &mut p3a,
      &mut p3b,
      &mut p3c,
      &mut t3,
    )
    .expect("3-input prover");

    // 5-input run with M = Q = 0
    let mut p5a = MultilinearPolynomial::new(a);
    let mut p5b = MultilinearPolynomial::new(b);
    let mut p5c = MultilinearPolynomial::new(c);
    let mut p5m = MultilinearPolynomial::new(zero.clone());
    let mut p5q = MultilinearPolynomial::new(zero);
    let mut t5 = E::TE::new(b"compare");
    let (proof5, r5, evals5) = SumcheckProof::<E>::prove_cubic_with_five_inputs(
      &claim, tau, &mut p5a, &mut p5b, &mut p5c, &mut p5m, &mut p5q, &mut t5,
    )
    .expect("5-input prover");

    assert_eq!(r3, r5, "challenge vectors differ");
    assert_eq!(evals3[0], evals5[0]);
    assert_eq!(evals3[1], evals5[1]);
    assert_eq!(evals3[2], evals5[2]);
    assert_eq!(evals5[3], E::Scalar::ZERO);
    assert_eq!(evals5[4], E::Scalar::ZERO);

    let bytes3 = bincode::serialize(&proof3).unwrap();
    let bytes5 = bincode::serialize(&proof5).unwrap();
    assert_eq!(
      bytes3, bytes5,
      "5-input proof should match 3-input when M=Q=0"
    );
  }

  /// Verifier must reject a tampered proof. Flip a coefficient in one of the
  /// compressed round polynomials.
  fn verifier_rejects_tamper_with<E: Engine>() {
    const SEED: u64 = 0x1234_5678;
    let num_vars = 4usize;
    let n = 1usize << num_vars;
    let mut rng = StdRng::seed_from_u64(SEED);

    let a: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let b: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let m: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let q: Vec<_> = (0..n).map(|_| E::Scalar::random(&mut rng)).collect();
    let c: Vec<_> = (0..n).map(|i| a[i] * b[i] - m[i] * q[i]).collect();
    let tau: Vec<_> = (0..num_vars).map(|_| E::Scalar::random(&mut rng)).collect();

    let mut p_t = E::TE::new(b"tamper");
    let (proof, _r, _evals) = SumcheckProof::<E>::prove_cubic_with_five_inputs(
      &E::Scalar::ZERO,
      tau,
      &mut MultilinearPolynomial::new(a),
      &mut MultilinearPolynomial::new(b),
      &mut MultilinearPolynomial::new(c),
      &mut MultilinearPolynomial::new(m),
      &mut MultilinearPolynomial::new(q),
      &mut p_t,
    )
    .expect("prover");

    // The SC verifier rebuilds the omitted linear coeff from the running
    // claim, so swapping in another degree-3 poly is silently absorbed. The
    // observable failure modes from `verify` alone are:
    //   (a) wrong number of round polys, and
    //   (b) a round poly that decompresses to the wrong degree.
    // Each is exercised below.

    // (a) Drop the last round poly.
    let bytes = bincode::serialize(&proof).unwrap();
    let mut short: SumcheckProof<E> = bincode::deserialize(&bytes).unwrap();
    short.compressed_polys.pop();
    let mut v_t = E::TE::new(b"tamper");
    assert!(
      short
        .verify(E::Scalar::ZERO, num_vars, 3, &mut v_t)
        .is_err()
    );

    // (b) Replace round 0 with a degree-2 polynomial.
    let mut wrong_degree: SumcheckProof<E> = bincode::deserialize(&bytes).unwrap();
    let low_degree =
      UniPoly::from_evals(&[E::Scalar::ZERO, E::Scalar::ZERO, E::Scalar::ZERO]).unwrap();
    wrong_degree.compressed_polys[0] = low_degree.compress();
    let mut v_t = E::TE::new(b"tamper");
    assert!(
      wrong_degree
        .verify(E::Scalar::ZERO, num_vars, 3, &mut v_t)
        .is_err()
    );

    // Sanity: the untampered proof still verifies.
    let mut v_t = E::TE::new(b"tamper");
    assert!(proof.verify(E::Scalar::ZERO, num_vars, 3, &mut v_t).is_ok());
  }

  #[test]
  fn test_five_input_random_correctness() {
    use crate::provider::{Bn254Engine, PallasHyraxEngine, T256HyraxEngine};
    random_correctness_with::<Bn254Engine>();
    random_correctness_with::<PallasHyraxEngine>();
    random_correctness_with::<T256HyraxEngine>();
  }

  #[test]
  fn test_five_input_zero_check() {
    use crate::provider::{Bn254Engine, PallasHyraxEngine, T256HyraxEngine};
    zero_check_correctness_with::<Bn254Engine>();
    zero_check_correctness_with::<PallasHyraxEngine>();
    zero_check_correctness_with::<T256HyraxEngine>();
  }

  #[test]
  fn test_five_input_matches_three_input_when_mq_zero() {
    use crate::provider::{Bn254Engine, PallasHyraxEngine, T256HyraxEngine};
    matches_three_input_when_mq_zero_with::<Bn254Engine>();
    matches_three_input_when_mq_zero_with::<PallasHyraxEngine>();
    matches_three_input_when_mq_zero_with::<T256HyraxEngine>();
  }

  #[test]
  fn test_five_input_verifier_rejects_tampering() {
    use crate::provider::{Bn254Engine, PallasHyraxEngine, T256HyraxEngine};
    verifier_rejects_tamper_with::<Bn254Engine>();
    verifier_rejects_tamper_with::<PallasHyraxEngine>();
    verifier_rejects_tamper_with::<T256HyraxEngine>();
  }
}
